/** Reserved words that cannot be used as bare ESM const declarations. */
export const RESERVED_IDENT = new Set([
    "break", "case", "catch", "class", "const", "continue", "debugger", "default",
    "delete", "do", "else", "export", "extends", "false", "finally", "for",
    "function", "if", "import", "in", "instanceof", "new", "null", "return",
    "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void",
    "while", "with", "yield", "enum", "let", "static", "await", "interface",
    "implements", "package", "private", "protected", "public",
]);
/** Keep the persisted refName unchanged while avoiding local import collisions. */
export function safeIdentifier(refName, ...importNames) {
    return RESERVED_IDENT.has(refName) || importNames.includes(refName) ? `${refName}_` : refName;
}
